{
  "name": "CarouselFuzz Pro",
  "description": "An ultra-premium AI-powered social media carousel generator using the WebJSON technique to search, structure, and generate stunning visuals with Gemini.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Slide {
  id: string;
  headline: string;
  body: string;
  visualPrompt: string;
  imageUri?: string;
  layout: 'center' | 'bottom' | 'split' | 'minimal';
}

export interface CarouselConfig {
  title: string;
  accentColor: string;
  fontFamily: string;
  aspectRatio: '1:1' | '4:5';
  slides: Slide[];
}

export enum ExportFormat {
  SQUARE = '1080x1080',
  VERTICAL = '1080x1350'
}

export interface GenerationState {
  isGeneratingContent: boolean;
  isGeneratingImages: boolean;
  progress: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { CarouselConfig, Slide } from "./types";

const API_KEY = process.env.API_KEY || "";

export const generateCarouselContent = async (topic: string): Promise<CarouselConfig> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `You are an expert social media content strategist. 
    Topic: ${topic}

    Research this topic and create a high-impact social media carousel.
    Structure: 5-7 slides.
    For each slide, provide:
    1. A punchy headline.
    2. Concise, engaging body text.
    3. A detailed visual prompt for an AI image generator (2D flat illustration, minimal style, tech-focused, professional).

    Return a JSON object matching the CarouselConfig schema.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          accentColor: { type: Type.STRING, description: "A hex code that fits the topic vibe" },
          fontFamily: { type: Type.STRING, description: "Suggest 'Space Grotesk' or 'Plus Jakarta Sans'" },
          aspectRatio: { type: Type.STRING, enum: ["1:1", "4:5"] },
          slides: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                headline: { type: Type.STRING },
                body: { type: Type.STRING },
                visualPrompt: { type: Type.STRING },
                layout: { type: Type.STRING, enum: ["center", "bottom", "split", "minimal"] }
              },
              required: ["headline", "body", "visualPrompt", "layout"]
            }
          }
        },
        required: ["title", "accentColor", "slides"]
      }
    }
  });

  const config = JSON.parse(response.text) as CarouselConfig;
  // Add IDs to slides
  config.slides = config.slides.map((s, idx) => ({ ...s, id: `slide-${idx}` }));
  return config;
};

export const generateSlideImage = async (prompt: string, aspectRatio: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const ratio = aspectRatio === '4:5' ? '3:4' : '1:1'; // Gemini uses standard ratios

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [{ text: `${prompt}. High quality, 4k, clean composition, studio lighting, professional graphic design style.` }],
    },
    config: {
      imageConfig: {
        aspectRatio: ratio as any,
      }
    }
  });

  for (const part of response.candidates?.[0]?.content.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("Failed to generate image");
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  Sparkles, 
  Settings, 
  Image as ImageIcon, 
  Download, 
  Plus, 
  Trash2, 
  ChevronLeft, 
  ChevronRight,
  Monitor,
  Smartphone,
  Layers,
  Palette,
  Type as TypeIcon,
  Cpu,
  Loader2,
  Zap
} from 'lucide-react';
import { CarouselConfig, Slide, GenerationState } from './types';
import { generateCarouselContent, generateSlideImage } from './geminiService';

// --- Sub-components ---

const GlassButton: React.FC<{ 
  onClick?: () => void; 
  children: React.ReactNode; 
  active?: boolean; 
  className?: string;
  disabled?: boolean;
}> = ({ onClick, children, active, className, disabled }) => (
  <button
    disabled={disabled}
    onClick={onClick}
    className={`px-4 py-2 rounded-xl transition-all duration-300 flex items-center gap-2 text-sm font-semibold
      ${active 
        ? 'bg-teal-500 text-white neon-glow' 
        : 'bg-white/5 hover:bg-white/10 text-slate-300 border border-white/10'}
      ${disabled ? 'opacity-50 cursor-not-allowed' : ''}
      ${className}`}
  >
    {children}
  </button>
);

const Sidebar: React.FC<{
  config: CarouselConfig;
  currentSlideIndex: number;
  onSelectSlide: (idx: number) => void;
  onUpdateSlide: (idx: number, updates: Partial<Slide>) => void;
  onAddSlide: () => void;
  onDeleteSlide: (idx: number) => void;
  onUpdateConfig: (updates: Partial<CarouselConfig>) => void;
}> = ({ config, currentSlideIndex, onSelectSlide, onUpdateSlide, onAddSlide, onDeleteSlide, onUpdateConfig }) => {
  return (
    <div className="w-80 h-full border-r border-white/5 p-6 flex flex-col gap-8 overflow-y-auto">
      <div>
        <h2 className="text-xs font-bold uppercase tracking-widest text-slate-500 mb-4 flex items-center gap-2">
          <Layers size={14} /> Project Config
        </h2>
        <div className="space-y-4">
          <div>
            <label className="text-xs text-slate-400 mb-1 block">Project Title</label>
            <input 
              className="w-full bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-teal-500/50"
              value={config.title}
              onChange={(e) => onUpdateConfig({ title: e.target.value })}
            />
          </div>
          <div className="flex gap-4">
            <div className="flex-1">
              <label className="text-xs text-slate-400 mb-1 block">Accent Color</label>
              <div className="flex gap-2 items-center">
                <input 
                  type="color"
                  className="w-8 h-8 rounded-full bg-transparent border-none cursor-pointer"
                  value={config.accentColor}
                  onChange={(e) => onUpdateConfig({ accentColor: e.target.value })}
                />
                <span className="text-xs font-mono">{config.accentColor}</span>
              </div>
            </div>
            <div className="flex-1">
              <label className="text-xs text-slate-400 mb-1 block">Format</label>
              <select 
                className="w-full bg-white/5 border border-white/10 rounded-lg px-2 py-1.5 text-xs"
                value={config.aspectRatio}
                onChange={(e) => onUpdateConfig({ aspectRatio: e.target.value as any })}
              >
                <option value="1:1">Square (1:1)</option>
                <option value="4:5">Vertical (4:5)</option>
              </select>
            </div>
          </div>
        </div>
      </div>

      <div>
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xs font-bold uppercase tracking-widest text-slate-500 flex items-center gap-2">
            <Smartphone size={14} /> Slides
          </h2>
          <button onClick={onAddSlide} className="text-teal-400 hover:text-teal-300">
            <Plus size={18} />
          </button>
        </div>
        <div className="space-y-2">
          {config.slides.map((slide, idx) => (
            <div 
              key={slide.id}
              onClick={() => onSelectSlide(idx)}
              className={`group flex items-center justify-between p-3 rounded-xl cursor-pointer border transition-all duration-200
                ${currentSlideIndex === idx 
                  ? 'bg-teal-500/10 border-teal-500/50 text-teal-100' 
                  : 'bg-white/5 border-white/5 hover:bg-white/10 text-slate-400'}`}
            >
              <div className="flex items-center gap-3">
                <span className="text-xs font-bold opacity-50">{idx + 1}</span>
                <span className="text-sm font-medium truncate w-40">{slide.headline || 'Untitled Slide'}</span>
              </div>
              <button 
                onClick={(e) => { e.stopPropagation(); onDeleteSlide(idx); }}
                className="opacity-0 group-hover:opacity-100 text-slate-500 hover:text-red-400 transition-opacity"
              >
                <Trash2 size={14} />
              </button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const SlidePreview: React.FC<{ 
  slide: Slide; 
  config: CarouselConfig;
  isExport?: boolean;
}> = ({ slide, config, isExport }) => {
  const isVertical = config.aspectRatio === '4:5';

  return (
    <div 
      className={`relative overflow-hidden rounded-2xl shadow-2xl transition-all duration-500
        ${isExport ? 'w-[1080px]' : isVertical ? 'h-[500px] aspect-[4/5]' : 'h-[500px] aspect-square'}`}
      style={{ 
        backgroundColor: '#0f172a',
        fontFamily: config.fontFamily || 'Inter'
      }}
    >
      {/* Background Image with Overlay */}
      {slide.imageUri ? (
        <img src={slide.imageUri} className="absolute inset-0 w-full h-full object-cover" alt="Background" />
      ) : (
        <div className="absolute inset-0 bg-gradient-to-br from-slate-900 to-slate-800" />
      )}

      {/* Dynamic Overlay Gradient */}
      <div 
        className="absolute inset-0 opacity-80"
        style={{ background: `linear-gradient(to bottom, transparent 0%, rgba(0,0,0,0.8) 100%)` }}
      />

      {/* Branding */}
      <div className="absolute top-6 left-8 flex items-center gap-2">
        <div className="w-8 h-8 rounded-lg bg-teal-500 flex items-center justify-center shadow-lg neon-glow">
          <Zap size={16} className="text-white fill-current" />
        </div>
        <span className="text-xs font-bold tracking-widest text-white/50 uppercase">CarouselFuzz</span>
      </div>

      {/* Content Layouts */}
      <div className="absolute inset-0 p-12 flex flex-col justify-end">
        <div className={`space-y-4 max-w-full ${slide.layout === 'center' ? 'text-center items-center' : ''}`}>
          <h1 
            className="text-4xl md:text-5xl font-extrabold text-white leading-tight drop-shadow-lg"
            style={{ color: '#fff' }}
          >
            {slide.headline.split('{').map((part, i) => {
              if (part.includes('}')) {
                const [highlight, rest] = part.split('}');
                return <React.Fragment key={i}><span style={{ color: config.accentColor }}>{highlight}</span>{rest}</React.Fragment>;
              }
              return part;
            })}
          </h1>
          <p className="text-lg text-slate-200/90 leading-relaxed font-medium drop-shadow-md">
            {slide.body.split('{').map((part, i) => {
              if (part.includes('}')) {
                const [highlight, rest] = part.split('}');
                return <React.Fragment key={i}><span className="underline decoration-teal-500/50">{highlight}</span>{rest}</React.Fragment>;
              }
              return part;
            })}
          </p>
        </div>
      </div>

      {/* Slide Indicator */}
      <div className="absolute bottom-6 right-8 text-xs font-bold font-mono text-white/30 tracking-tighter">
        0{config.slides.indexOf(slide) + 1} / 0{config.slides.length}
