    </div>
  );
};

export default function App() {
  const [config, setConfig] = useState<CarouselConfig>({
    title: 'New Strategy',
    accentColor: '#2dd4bf',
    fontFamily: 'Plus Jakarta Sans',
    aspectRatio: '4:5',
    slides: [
      {
        id: '1',
        headline: 'Welcome to {CarouselFuzz} Pro',
        body: 'Enter a topic to generate your first {automated} carousel.',
        visualPrompt: 'Minimal futuristic workspace, neon highlights, 3D render style',
        layout: 'center'
      }
    ]
  });

  const [currentIdx, setCurrentIdx] = useState(0);
  const [topic, setTopic] = useState('');
  const [isAgentOpen, setIsAgentOpen] = useState(false);
  const [genState, setGenState] = useState<GenerationState>({
    isGeneratingContent: false,
    isGeneratingImages: false,
    progress: 0
  });

  const handleGenerateContent = async () => {
    if (!topic) return;
    setGenState(prev => ({ ...prev, isGeneratingContent: true }));
    try {
      const newConfig = await generateCarouselContent(topic);
      setConfig(newConfig);
      setCurrentIdx(0);
      setIsAgentOpen(false);
    } catch (err) {
      console.error(err);
      alert("Error generating content. Check console.");
    } finally {
      setGenState(prev => ({ ...prev, isGeneratingContent: false }));
    }
  };

  const handleGenerateImages = async () => {
    setGenState(prev => ({ ...prev, isGeneratingImages: true, progress: 0 }));
    const updatedSlides = [...config.slides];

    for (let i = 0; i < updatedSlides.length; i++) {
      try {
        const imageUri = await generateSlideImage(updatedSlides[i].visualPrompt, config.aspectRatio);
        updatedSlides[i] = { ...updatedSlides[i], imageUri };
        setConfig(prev => ({ ...prev, slides: updatedSlides }));
        setGenState(prev => ({ ...prev, progress: Math.round(((i + 1) / updatedSlides.length) * 100) }));
      } catch (err) {
        console.error(err);
      }
    }
    setGenState(prev => ({ ...prev, isGeneratingImages: false }));
  };

  const updateSlide = (idx: number, updates: Partial<Slide>) => {
    const updated = [...config.slides];
    updated[idx] = { ...updated[idx], ...updates };
    setConfig({ ...config, slides: updated });
  };

  const addSlide = () => {
    const newSlide: Slide = {
      id: Math.random().toString(36).substr(2, 9),
      headline: 'New Headline',
      body: 'Description goes here...',
      visualPrompt: 'Describe the scene',
      layout: 'center'
    };
    setConfig({ ...config, slides: [...config.slides, newSlide] });
    setCurrentIdx(config.slides.length);
  };

  const deleteSlide = (idx: number) => {
    if (config.slides.length <= 1) return;
    const filtered = config.slides.filter((_, i) => i !== idx);
    setConfig({ ...config, slides: filtered });
    setCurrentIdx(Math.max(0, idx - 1));
  };

  return (
    <div className="flex h-screen bg-[#030712] text-slate-100 overflow-hidden">

      {/* Sidebar Controls */}
      <Sidebar 
        config={config} 
        currentSlideIndex={currentIdx}
        onSelectSlide={setCurrentIdx}
        onUpdateSlide={updateSlide}
        onAddSlide={addSlide}
        onDeleteSlide={deleteSlide}
        onUpdateConfig={(updates) => setConfig({ ...config, ...updates })}
      />

      {/* Main Workspace */}
      <main className="flex-1 flex flex-col">

        {/* Header Navigation */}
        <header className="h-16 border-b border-white/5 px-8 flex items-center justify-between">
          <div className="flex items-center gap-6">
             <div className="flex items-center gap-2">
                <span className="text-xl font-extrabold tracking-tighter text-white">Carousel<span className="text-teal-400">Fuzz</span></span>
                <span className="bg-teal-500/20 text-teal-400 text-[10px] px-1.5 py-0.5 rounded font-bold uppercase tracking-widest border border-teal-500/20">Pro</span>
             </div>
          </div>

          <div className="flex items-center gap-3">
             <GlassButton onClick={() => setIsAgentOpen(true)}>
               <Sparkles size={16} /> AI Agent
             </GlassButton>
             <GlassButton onClick={handleGenerateImages} disabled={genState.isGeneratingImages}>
               {genState.isGeneratingImages ? <Loader2 size={16} className="animate-spin" /> : <ImageIcon size={16} />} 
               Generate Assets
             </GlassButton>
             <div className="w-px h-6 bg-white/10 mx-2" />
             <GlassButton active>
               <Download size={16} /> Export ZIP
             </GlassButton>
          </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 flex overflow-hidden">

          {/* Canvas Wrapper */}
          <div className="flex-1 p-12 flex flex-col items-center justify-center bg-[#070b14] relative overflow-auto">
            <div className="absolute top-8 left-1/2 -translate-x-1/2 flex gap-4">
               <button onClick={() => setCurrentIdx(p => Math.max(0, p - 1))} className="p-2 bg-white/5 rounded-full hover:bg-white/10 transition-colors">
                 <ChevronLeft />
               </button>
               <span className="text-sm font-bold self-center bg-white/5 px-4 py-1 rounded-full border border-white/10">Slide {currentIdx + 1} / {config.slides.length}</span>
               <button onClick={() => setCurrentIdx(p => Math.min(config.slides.length - 1, p + 1))} className="p-2 bg-white/5 rounded-full hover:bg-white/10 transition-colors">
                 <ChevronRight />
               </button>
            </div>

            <div className="relative group">
              <SlidePreview slide={config.slides[currentIdx]} config={config} />

              {/* Floating Action Buttons */}
              <div className="absolute -right-16 top-0 flex flex-col gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                 <button className="p-3 bg-white/5 rounded-xl border border-white/10 text-white hover:bg-teal-500 transition-all hover:scale-110">
                   <Monitor size={18} />
                 </button>
                 <button className="p-3 bg-white/5 rounded-xl border border-white/10 text-white hover:bg-teal-500 transition-all hover:scale-110">
                   <Palette size={18} />
                 </button>
              </div>
            </div>

            {/* Live Progress Bar for Image Gen */}
            {genState.isGeneratingImages && (
              <div className="absolute bottom-8 w-64 bg-white/5 rounded-full h-1 overflow-hidden">
                <div 
                  className="bg-teal-500 h-full transition-all duration-500" 
                  style={{ width: `${genState.progress}%` }} 
                />
              </div>
            )}
          </div>

          {/* Quick Edit Panel */}
          <div className="w-96 border-l border-white/5 p-8 flex flex-col gap-6 overflow-y-auto">
            <h2 className="text-xs font-bold uppercase tracking-widest text-slate-500 flex items-center gap-2">
              <Settings size={14} /> Slide Editor
            </h2>

            <div className="space-y-6">
              <div>
                <label className="text-xs text-slate-400 mb-2 block">Headline (Use {'{'}text{'}'} for highlights)</label>
                <textarea 
                  className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm font-medium focus:outline-none focus:border-teal-500/50 min-h-[80px]"
                  value={config.slides[currentIdx].headline}
                  onChange={(e) => updateSlide(currentIdx, { headline: e.target.value })}
                />
              </div>

              <div>
                <label className="text-xs text-slate-400 mb-2 block">Body Text</label>
                <textarea 
                  className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm text-slate-300 leading-relaxed focus:outline-none focus:border-teal-500/50 min-h-[120px]"
                  value={config.slides[currentIdx].body}
                  onChange={(e) => updateSlide(currentIdx, { body: e.target.value })}
                />
              </div>

              <div>
                <label className="text-xs text-slate-400 mb-2 block">Visual Prompt</label>
                <div className="relative">
                  <textarea 
                    className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-xs text-slate-400 focus:outline-none focus:border-teal-500/50 min-h-[60px]"
                    value={config.slides[currentIdx].visualPrompt}
                    onChange={(e) => updateSlide(currentIdx, { visualPrompt: e.target.value })}
                  />
                  <button 
                    onClick={async () => {
                      const uri = await generateSlideImage(config.slides[currentIdx].visualPrompt, config.aspectRatio);
                      updateSlide(currentIdx, { imageUri: uri });
                    }}
                    className="absolute bottom-2 right-2 p-1.5 rounded-lg bg-teal-500/20 text-teal-400 hover:bg-teal-500/40"
                  >
                    <ImageIcon size={14} />
                  </button>
                </div>
              </div>

              <div>
                <label className="text-xs text-slate-400 mb-2 block">Layout</label>
                <div className="grid grid-cols-2 gap-2">
                  {['center', 'bottom', 'split', 'minimal'].map((lay) => (
                    <button
                      key={lay}
                      onClick={() => updateSlide(currentIdx, { layout: lay as any })}
                      className={`px-3 py-2 rounded-lg text-xs font-semibold capitalize border transition-all
                        ${config.slides[currentIdx].layout === lay 
                          ? 'bg-teal-500/20 border-teal-500/50 text-teal-400' 
                          : 'bg-white/5 border-white/5 text-slate-500 hover:bg-white/10'}`}
                    >
                      {lay}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      </main>

      {/* AI Agent Modal */}
      {isAgentOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6">
          <div 
            className="absolute inset-0 bg-black/60 backdrop-blur-sm" 
            onClick={() => !genState.isGeneratingContent && setIsAgentOpen(false)}
          />
          <div className="relative glass w-full max-w-lg rounded-3xl p-8 border border-white/10 shadow-2xl">
            <div className="flex items-center gap-3 mb-6">
              <div className="w-10 h-10 rounded-2xl bg-teal-500 flex items-center justify-center neon-glow">
                <Sparkles size={20} className="text-white" />
              </div>
              <div>
                <h2 className="text-xl font-bold">CarouselFuzz AI Agent</h2>
                <p className="text-sm text-slate-400">Describe your topic, I'll build the strategy.</p>
              </div>
            </div>

            <div className="space-y-4">
              <textarea 
                placeholder="Ex: 5 tips for Web3 developers to scale their dApps in 2025..."
                className="w-full bg-white/5 border border-white/10 rounded-2xl p-4 text-sm focus:outline-none focus:border-teal-500 transition-colors min-h-[120px]"
                value={topic}
                onChange={(e) => setTopic(e.target.value)}
                disabled={genState.isGeneratingContent}
              />
              <div className="flex gap-3">
                <button 
                  onClick={() => setIsAgentOpen(false)}
                  className="flex-1 py-3 text-sm font-bold text-slate-400 hover:text-white transition-colors"
                  disabled={genState.isGeneratingContent}
                >
                  Cancel
                </button>
                <button 
                  onClick={handleGenerateContent}
                  disabled={!topic || genState.isGeneratingContent}
                  className="flex-[2] py-3 bg-teal-500 rounded-xl text-sm font-bold text-white shadow-lg neon-glow disabled:opacity-50 disabled:neon-glow-none flex items-center justify-center gap-2"
                >
                  {genState.isGeneratingContent ? (
                    <>
                      <Loader2 size={16} className="animate-spin" />
                      Analyzing...
                    </>
                  ) : (
                    <>
                      Build Carousel
                      <Zap size={16} />
                    </>
                  )}
                </button>
              </div>
            </div>

            <div className="mt-8 pt-6 border-t border-white/5">
               <p className="text-[10px] uppercase tracking-widest font-bold text-slate-500 text-center">Powered by Gemini WebJSON Technique</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { GoogleGenAI, Type } from "@google/genai";
import { CarouselConfig, Slide } from "./types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const generateCarouselContent = async (topic: string, imageBase64?: string): Promise<CarouselConfig> => {
  const ai = getAI();

  const contents: any[] = [
    {
      text: `You are an expert social media content strategist. 
      Topic: ${topic}
      ${imageBase64 ? "The user has also provided an image for inspiration/analysis. Use its visual style or context." : ""}

      TASK: Research this topic using the web (WebJSON technique) to find the most recent trends and data.
      Create a high-impact social media carousel (5-10 slides).

      For each slide, provide:
      1. A punchy headline (use {text} for words to be highlighted).
      2. Concise, engaging body text.
      3. A detailed visual prompt for an AI image generator.
      4. A layout recommendation.

      Return a valid JSON object matching the CarouselConfig schema.`
    }
  ];

  if (imageBase64) {
    contents.push({
      inlineData: {
        mimeType: "image/jpeg",
        data: imageBase64.split(',')[1]
      }
    });
  }

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: { parts: contents },
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          accentColor: { type: Type.STRING },
          fontFamily: { type: Type.STRING },
          aspectRatio: { type: Type.STRING, enum: ["1:1", "4:5"] },
          slides: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                headline: { type: Type.STRING },
                body: { type: Type.STRING },
                visualPrompt: { type: Type.STRING },
                layout: { type: Type.STRING, enum: ["center", "bottom", "split", "minimal"] }
              },
              required: ["headline", "body", "visualPrompt", "layout"]
            }
          }
        },
        required: ["title", "accentColor", "slides"]
      }
    }
  });

  const config = JSON.parse(response.text) as CarouselConfig;
  config.slides = config.slides.map((s, idx) => ({ ...s, id: `slide-${idx}-${Date.now()}` }));
  return config;
};

export const generateSlideImage = async (prompt: string, aspectRatio: string): Promise<string> => {
  const ai = getAI();
  const ratio = aspectRatio === '4:5' ? '3:4' : '1:1';

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [{ text: `${prompt}. Ultra-professional graphic design, high resolution, clean background, modern aesthetics.` }],
    },
    config: {
      imageConfig: {
        aspectRatio: ratio as any,
      }
    }
  });

  for (const part of response.candidates?.[0]?.content.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("Failed to generate image");
};

