export default function App() {
  const [config, setConfig] = useState<CarouselConfig>({
    title: 'New Strategy',
    accentColor: '#2dd4bf',
    fontFamily: 'Plus Jakarta Sans',
    aspectRatio: '4:5',
    slides: [
      {
        id: '1',
        headline: 'Welcome to {CarouselFuzz} Pro',
        body: 'Describe a topic in the {AI Agent} to build your first professional carousel.',
        visualPrompt: 'Futuristic abstract digital world, neon colors, glass elements, high tech',
        layout: 'center'
      }
    ]
  });

  const [currentIdx, setCurrentIdx] = useState(0);
  const [topic, setTopic] = useState('');
  const [isAgentOpen, setIsAgentOpen] = useState(false);
  const [imageBase64, setImageBase64] = useState<string | null>(null);
  const [isExporting, setIsExporting] = useState(false);
  const [genState, setGenState] = useState<GenerationState>({
    isGeneratingContent: false,
    isGeneratingImages: false,
    progress: 0
  });

  const previewRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleGenerateContent = async () => {
    if (!topic) return;
    setGenState(prev => ({ ...prev, isGeneratingContent: true }));
    try {
      const newConfig = await generateCarouselContent(topic, imageBase64 || undefined);
      setConfig(newConfig);
      setCurrentIdx(0);
      setIsAgentOpen(false);
      setImageBase64(null);
    } catch (err) {
      console.error(err);
      alert("API Error. Please check your credentials.");
    } finally {
      setGenState(prev => ({ ...prev, isGeneratingContent: false }));
    }
  };

  const handleGenerateImages = async () => {
    setGenState(prev => ({ ...prev, isGeneratingImages: true, progress: 0 }));
    const updatedSlides = [...config.slides];

    for (let i = 0; i < updatedSlides.length; i++) {
      try {
        const imageUri = await generateSlideImage(updatedSlides[i].visualPrompt, config.aspectRatio);
        updatedSlides[i] = { ...updatedSlides[i], imageUri };
        setConfig(prev => ({ ...prev, slides: [...updatedSlides] }));
        setGenState(prev => ({ ...prev, progress: Math.round(((i + 1) / updatedSlides.length) * 100) }));
      } catch (err) {
        console.error("Image Gen Error:", err);
      }
    }
    setGenState(prev => ({ ...prev, isGeneratingImages: false }));
  };

  const handleExportZip = async () => {
    setIsExporting(true);
    const zip = new JSZip();
    const folder = zip.folder("carousel-slides");

    try {
      for (let i = 0; i < config.slides.length; i++) {
        setCurrentIdx(i);
        // Small delay to ensure render
        await new Promise(resolve => setTimeout(resolve, 500));

        const node = document.getElementById(`preview-${config.slides[i].id}`);
        if (node) {
          const dataUrl = await htmlToImage.toPng(node, { 
            quality: 1, 
            pixelRatio: 2,
            width: 1080,
            height: config.aspectRatio === '4:5' ? 1350 : 1080
          });
          const base64Data = dataUrl.replace(/^data:image\/(png|jpg);base64,/, "");
          folder?.file(`slide-${i + 1}.png`, base64Data, { base64: true });
        }
      }

      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(content);
      link.download = `${config.title.toLowerCase().replace(/\s+/g, '-')}-carousel.zip`;
      link.click();
    } catch (err) {
      console.error("Export Error:", err);
      alert("Failed to export ZIP. Check browser console.");
    } finally {
      setIsExporting(false);
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImageBase64(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const updateSlide = (idx: number, updates: Partial<Slide>) => {
    const updated = [...config.slides];
    updated[idx] = { ...updated[idx], ...updates };
    setConfig({ ...config, slides: updated });
  };

  return (
    <div className="flex h-screen bg-[#030712] text-slate-100 overflow-hidden font-['Plus_Jakarta_Sans']">

      <Sidebar 
        config={config} 
        currentSlideIndex={currentIdx}
        onSelectSlide={setCurrentIdx}
        onAddSlide={() => {
          const newSlide: Slide = { id: Date.now().toString(), headline: 'New {Slide}', body: 'Edit your content...', visualPrompt: 'Abstract design', layout: 'center' };
          setConfig(prev => ({ ...prev, slides: [...prev.slides, newSlide] }));
          setCurrentIdx(config.slides.length);
        }}
        onDeleteSlide={(idx) => {
          if (config.slides.length <= 1) return;
          const filtered = config.slides.filter((_, i) => i !== idx);
          setConfig(prev => ({ ...prev, slides: filtered }));
          setCurrentIdx(Math.max(0, idx - 1));
        }}
        onUpdateConfig={(updates) => setConfig(prev => ({ ...prev, ...updates }))}
      />

