      </main>

      {/* AI Strategist Modal */}
      {isAgentOpen && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-8">
          <div 
            className="absolute inset-0 bg-black/80 backdrop-blur-2xl transition-opacity animate-in fade-in" 
