                  const newSlide: Slide = { id: Date.now().toString(), headline: 'New {Heading}', body: 'Edit me...', visualPrompt: 'Abstract art', layout: 'center', overlayOpacity: 0.8 };
                  setConfig({...config, slides: [...config.slides, newSlide]});
